 14	}
 15	
 16	const SyncContext = createContext<SyncContextValue | undefined>(undefined);
 17	
 18	/**
 19	 * useSyncContext Hook
 20	 *
 21	 * 컴포넌트에서 동기화 상태와 수동 트리거 접근
