  3	import { syncData } from './engine';
  4	
  5	/**
  6	 * SyncProvider Context
  7	 *
  8	 * 동기화 상태와 수동 트리거 제공
  9	 */
 10	interface SyncContextValue {
 11	  isSyncing: boolean;
 12	  lastSyncedAt: Date | null;
 13	  triggerManualSync: () => Promise<void>;
 14	}
