    30	    delete: CRUDPermission;
    31	  };
    32	  expense: {
    33	    create: CRUDPermission;
    34	    read: CRUDPermission;
    35	    update: CRUDPermission;
    36	    delete: CRUDPermission;
    37	  };
    38	  service: ServiceConfig;
    39	}
    40	
    41	/**
    42	 * 앱 전역 Policy Hook
    43	 *
    44	 * @param tripId - Trip ID (optional)
    45	 * @returns 모든 Entity의 CRUD 정책
    46	 *
    47	 * @example
    48	 * ```tsx
    49	 * // 여러 Entity 정책을 동시에 체크
    50	 * const policy = useAppPolicy(tripId);
    51	 *
    52	 * if (!policy.schedule.create.allowed) {
    53	 *   return <DisabledMessage reason={policy.schedule.create.reason} />;
    54	 * }
    55	 *
    56	 * if (policy.expense.create.mode === 'manual-only') {
    57	 *   return <ManualInputForm />;
    58	 * }
    59	 *
    60	 * // Service 설정도 접근 가능
