     7	
     8	import { useMemo } from 'react';
     9	import { useDisplayNetworkStatus } from '@/shared/store/network';
    10	import { useGetTripActivation } from '@/entities/trip/data/useGetTripActivation';
    11	import { TRIP_POLICIES, SCHEDULE_POLICIES, EXPENSE_POLICIES, SERVICE_POLICIES } from './constants';
