    13	
    14	/**
    15	 * App Policy Context
    16	 *
    17	 * 모든 Entity의 CRUD 정책 + Service 설정
    18	 */
    19	export interface AppPolicyContext {
    20	  trip: {
    21	    create: CRUDPermission;
    22	    read: CRUDPermission;
    23	    update: CRUDPermission;
    24	    delete: CRUDPermission;
    25	  };
    26	  schedule: {
    27	    create: CRUDPermission;
    28	    read: CRUDPermission;
    29	    update: CRUDPermission;
    30	    delete: CRUDPermission;
    31	  };
    32	  expense: {
    33	    create: CRUDPermission;
    34	    read: CRUDPermission;
    35	    update: CRUDPermission;
    36	    delete: CRUDPermission;
    37	  };
    38	  service: ServiceConfig;
    39	}
    40	
    41	/**
    42	 * 앱 전역 Policy Hook
    43	 *
    44	 * @param tripId - Trip ID (optional)
    45	 * @returns 모든 Entity의 CRUD 정책
    46	 *
    47	 * @example
    48	 * ```tsx
    49	 * // 여러 Entity 정책을 동시에 체크
    50	 * const policy = useAppPolicy(tripId);
    51	 *
    52	 * if (!policy.schedule.create.allowed) {
    53	 *   return <DisabledMessage reason={policy.schedule.create.reason} />;
    54	 * }
    55	 *
    56	 * if (policy.expense.create.mode === 'manual-only') {
    57	 *   return <ManualInputForm />;
    58	 * }
    59	 *
    60	 * // Service 설정도 접근 가능
    61	 * if (policy.service.mapProvider === 'mapbox') {
    62	 *   return <OfflineMap />;
    63	 * }
    64	 * ```
    65	 */
    66	export function useAppPolicy(tripId?: string): AppPolicyContext {
    67	  const networkStatus = useDisplayNetworkStatus();
    68	
    69	  const { data: activation } = useGetTripActivation(tripId ?? '');
    70	
    71	  const isActivated = activation?.isActivated ?? false;
    72	  const activationStatus: ActivationStatus = tripId && isActivated ? 'active' : 'inactive';
    73	
    74	  // unknown도 Remote 기능을 열지 않는다. 현재 4-state 권한 표의 제한 모드를 재사용한다.
    75	  const policyNetworkStatus = networkStatus === 'online' ? 'online' : 'offline';
    76	  const policyKey: PolicyKey = `${policyNetworkStatus}_${activationStatus}`;
    77	
    78	  return useMemo(
    79	    () => ({
    80	      trip: {
    81	        create: TRIP_POLICIES.create[policyKey],
    82	        read: TRIP_POLICIES.read[policyKey],
    83	        update: TRIP_POLICIES.update[policyKey],
    84	        delete: TRIP_POLICIES.delete[policyKey],
    85	      },
    86	      schedule: {
    87	        create: SCHEDULE_POLICIES.create[policyKey],
    88	        read: SCHEDULE_POLICIES.read[policyKey],
    89	        update: SCHEDULE_POLICIES.update[policyKey],
    90	        delete: SCHEDULE_POLICIES.delete[policyKey],
    91	      },
    92	      expense: {
    93	        create: EXPENSE_POLICIES.create[policyKey],
    94	        read: EXPENSE_POLICIES.read[policyKey],
    95	        update: EXPENSE_POLICIES.update[policyKey],
    96	        delete: EXPENSE_POLICIES.delete[policyKey],
    97	      },
    98	      service: SERVICE_POLICIES[policyKey],
    99	    }),
   100	    [policyKey],
   101	  );
   102	}
     1	/**
     2	 * Policy Layer Types (CRUD-Centric)
     3	 *
     4	 * 동작 중심 구조로 4-state policy matrix 정의
     5	 * - online_active: 온라인 + 활성화 (전체 기능)
     6	 * - online_inactive: 온라인 + 비활성 (서버 직접 접근)
     7	 * - offline_active: 오프라인 + 활성화 (수동 입력 모드)
     8	 * - offline_inactive: 오프라인 + 비활성 (읽기 전용)
     9	 */
    10	
    11	import type { NetworkStatus } from '@/shared/store/network';
    12	
    13	export type { NetworkStatus } from '@/shared/store/network';
    14	export type ActivationStatus = 'active' | 'inactive';
    15	
    16	// 실제 관측은 세 상태이며, 기존 권한 표는 unknown의 제한 모드를 offline과 공유한다.
    17	export type PolicyKey = `${Exclude<NetworkStatus, 'unknown'>}_${ActivationStatus}`;
    18	
    19	/**
    20	 * CRUD Operation Mode
    21	 *
    22	 * - full: 전체 기능 사용 가능
    23	 * - manual-only: 수동 입력만 가능 (API 호출 없이 텍스트만)
    24	 * - limited: 일부 필드만 수정 가능
    25	 */
    26	export type CRUDMode = 'full' | 'manual-only' | 'limited';
    27	
    28	/**
    29	 * CRUD Permission
    30	 */
    31	export interface CRUDPermission {
    32	  allowed: boolean;
    33	  mode?: CRUDMode;
    34	  reason?: string; // 비활성화된 경우 사용자에게 보여줄 이유
    35	
    36	  // 필드별 검증 규칙 (optional)
    37	  validation?: {
    38	    required?: string[]; // 필수 필드
    39	    optional?: string[]; // 선택 필드
    40	    allowed?: string[]; // 허용된 필드 (limited mode)
    41	    blocked?: string[]; // 차단된 필드 (limited mode)
    42	    enforced?: Record<string, unknown>; // 강제 값 (e.g., latitude: null)
    43	  };
    44	}
    45	
    46	/**
    47	 * CRUD Operation Policies
    48	 *
    49	 * 각 CRUD 동작이 4가지 상태에서 어떻게 동작하는지 정의
    50	 */
    51	export interface CRUDOperationPolicies {
    52	  create: Record<PolicyKey, CRUDPermission>;
    53	  read: Record<PolicyKey, CRUDPermission>;
    54	  update: Record<PolicyKey, CRUDPermission>;
    55	  delete: Record<PolicyKey, CRUDPermission>;
    56	}
    57	
    58	export type TripPolicies = CRUDOperationPolicies;
    59	export type SchedulePolicies = CRUDOperationPolicies;
    60	export type ExpensePolicies = CRUDOperationPolicies;
    61	
    62	/**
    63	 * Service Layer Configuration
    64	 *
    65	 * 서비스 레이어는 상태별 설정 (기존 구조 유지)
    66	 */
    67	export interface ServiceConfig {
    68	  mapProvider: 'google' | 'mapbox' | 'none';
    69	  searchMode: 'api' | 'cache' | 'disabled';
    70	  syncStrategy: 'immediate' | 'background' | 'manual' | 'disabled';
    71	  uiMode: 'full' | 'limited' | 'readonly';
    72	}
    73	
    74	/**
    75	 * Service Layer Policies
    76	 */
    77	export type ServicePolicies = Record<PolicyKey, ServiceConfig>;

