    39	    optional?: string[]; // 선택 필드
    40	    allowed?: string[]; // 허용된 필드 (limited mode)
    41	    blocked?: string[]; // 차단된 필드 (limited mode)
    42	    enforced?: Record<string, unknown>; // 강제 값 (e.g., latitude: null)
    43	  };
    44	}
    45	
    46	/**
    47	 * CRUD Operation Policies
