    49	 * 각 CRUD 동작이 4가지 상태에서 어떻게 동작하는지 정의
    50	 */
    51	export interface CRUDOperationPolicies {
    52	  create: Record<PolicyKey, CRUDPermission>;
    53	  read: Record<PolicyKey, CRUDPermission>;
    54	  update: Record<PolicyKey, CRUDPermission>;
    55	  delete: Record<PolicyKey, CRUDPermission>;
