  1	// ========================================
  2	// Trip Repository - 활성화 상태에 따른 Local/Remote 분기
  3	// ========================================
  4	
  5	import { routeTripQuery, routeTripMutation } from '@/shared/services/offline-prep/router';
  6	import * as TripLocal from '../lib/trip-local';
  7	import * as TripApi from '../api/trips';
  8	import type { Trip, CreateTripRequest, UpdateTripRequest, DeleteTripResponse } from '../model';
  9	
 10	/**
 11	 * Trip Repository
 12	 *
 13	 * - 활성화된 Trip 있음: Local DB 사용
 14	 * - 비활성 상태: Server API 사용
 15	 * - Router가 활성화 상태에 따라 자동 분기
 16	 */
 17	export const TripRepository = {
 18	  /**
 19	   * 모든 여행 조회
 20	   */
 21	  getAll: async (): Promise<Trip[]> => {
 22	    return await routeTripQuery({
 23	      local: () => TripLocal.getTripsLocal(),
 24	      remote: async () => {
 25	        const response = await TripApi.fetchAllTrips();
 26	        return response.data;
 27	      },
 28	    });
 29	  },
 30	
 31	  /**
 32	   * 특정 여행 조회
 33	   */
 34	  getById: async (id: string): Promise<Trip | undefined> => {
 35	    return await routeTripQuery({
 36	      local: () => TripLocal.getTripByIdLocal(id),
 37	      remote: async () => {
 38	        // TODO: fetchTripById API 필요시 추가
 39	        const response = await TripApi.fetchAllTrips();
 40	        return response.data.find((trip) => trip.id === id);
 41	      },
 42	    });
 43	  },
 44	
 45	  /**
 46	   * 여행 생성
 47	   */
 48	  create: async (data: CreateTripRequest): Promise<Trip> => {
 49	    return await routeTripMutation({
 50	      local: () => TripLocal.createTripLocal(data),
 51	      remote: () => TripApi.fetchCreateTrip(data),
 52	    });
 53	  },
 54	
 55	  /**
 56	   * 여행 수정
 57	   */
 58	  update: async (id: string, data: UpdateTripRequest): Promise<Trip> => {
 59	    return await routeTripMutation({
 60	      local: () => TripLocal.updateTripLocal(id, data),
 61	      remote: () => TripApi.fetchUpdateTrip(id, data),
 62	    });
 63	  },
 64	
 65	  /**
 66	   * 여행 삭제 (Soft Delete)
 67	   */
 68	  delete: async (id: string): Promise<DeleteTripResponse> => {
 69	    return await routeTripMutation({
 70	      local: () => TripLocal.deleteTripLocal(id),
 71	      remote: () => TripApi.fetchDeleteTrip(id),
 72	    });
 73	  },
 74	};
  1	// ========================================
  2	// Schedule Repository - 활성화 상태에 따른 Local/Remote 분기
  3	// ========================================
  4	
  5	import { routeChildQuery, routeChildMutation } from '@/shared/services/offline-prep/router';
  6	import * as ScheduleLocal from '../lib/schedule-local';
  7	import * as ScheduleApi from '../api/schedules';
  8	import type { Schedule, CreateScheduleRequest, UpdateScheduleRequest } from '../model';
  9	
 10	/**
 11	 * Schedule Repository
 12	 *
 13	 * - 활성화된 Trip: Local DB 사용
 14	 * - 비활성 Trip: Server API 사용
 15	 * - routeChildQuery/Mutation이 tripId 기반으로 자동 분기
 16	 */
 17	export const ScheduleRepository = {
 18	  /**
 19	   * 여행의 일정 목록 조회
 20	   */
 21	  getByTripId: async (tripId: string): Promise<Schedule[]> => {
 22	    return await routeChildQuery(tripId, {
 23	      local: () => ScheduleLocal.getSchedulesLocal(tripId),
 24	      remote: () => ScheduleApi.fetchSchedules(tripId),
 25	    });
 26	  },
 27	
 28	  /**
 29	   * 특정 일정 조회
 30	   * @param id - 일정 ID
 31	   * @param tripId - 여행 ID (라우팅 판단용)
 32	   */
 33	  getById: async (id: string, tripId: string): Promise<Schedule | undefined> => {
 34	    return await routeChildQuery(tripId, {
 35	      local: () => ScheduleLocal.getScheduleByIdLocal(id),
 36	      remote: () => ScheduleApi.fetchScheduleById(id),
 37	    });
 38	  },
 39	
 40	  /**
 41	   * 여행의 일정 개수 조회
 42	   * - 로컬 전용 (오프라인 지도 다운로드 트리거용)
 43	   */
 44	  getCount: async (tripId: string): Promise<number> => {
 45	    return await ScheduleLocal.getScheduleCountLocal(tripId);
 46	  },
 47	
 48	  /**
