    34	export function SyncProvider({
    35	  children,
    36	  isDatabaseReady,
    37	  enablePeriodicSync = false,
    38	  syncInterval = 5 * 60 * 1000,
    39	}: SyncProviderProps) {
    40	  const networkStatus = useRealNetworkStatus();
    41	  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
    42	  const isAuthInitialized = useAuthStore((state) => state.isInitialized);
    43	  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
    44	  const canSync =
    45	    isDatabaseReady && isAuthInitialized && isAuthenticated && networkStatus === 'online' && overrideStatus === null;
    46	
    47	  const [isSyncing, setIsSyncing] = useState(false);
    48	  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
    49	  const inFlightRef = useRef<Promise<SyncRunResult> | null>(null);
    50	  const databaseReadyRef = useRef(isDatabaseReady);
    51	  databaseReadyRef.current = isDatabaseReady;
    52	  const previouslyEligibleRef = useRef(false);
    53	
    54	  const executeSync = useCallback((): Promise<SyncRunResult> => {
    55	    // 이전 render의 callback과 자동/수동 호출도 같은 진행 중 실행을 기다린다.
    56	    if (inFlightRef.current) {
    57	      return inFlightRef.current;
    58	    }
    59	
    60	    let blockedMessage: string | null = null;
    61	    if (!databaseReadyRef.current) {
    62	      blockedMessage = '데이터베이스가 준비되지 않아 동기화할 수 없습니다.';
    63	    } else if (!authStore.isInitialized || !authStore.isAuthenticated) {
    64	      blockedMessage = '로그인 준비가 완료된 뒤 동기화할 수 있습니다.';
    65	    } else if (networkStore.override !== null) {
    66	      blockedMessage = '네트워크 강제 설정 중에는 동기화할 수 없습니다. 실제 상태로 되돌려 주세요.';
    67	    } else if (networkStore.realStatus !== 'online') {
    68	      blockedMessage = '인터넷 연결이 확인된 뒤 동기화할 수 있습니다.';
    69	    }
    70	    if (blockedMessage) {
    71	      return Promise.resolve({ status: 'blocked', message: blockedMessage });
    72	    }
    73	
    74	    let resolveRun!: (result: SyncRunResult) => void;
    75	    const run = new Promise<SyncRunResult>((resolve) => {
    76	      resolveRun = resolve;
    77	    });
    78	    // React 표시 상태를 갱신하기 전에 실행 소유권을 선점한다.
    79	    inFlightRef.current = run;
    80	    previouslyEligibleRef.current = true;
    81	    setIsSyncing(true);
    82	
    83	    (async () => {
    84	      let result: SyncRunResult;
    85	      try {
    86	        await syncData();
    87	        setLastSyncedAt(new Date());
    88	        // engine가 반환됐음을 뜻한다. queue 전체 반영 여부는 engine의 결과 계약에 따른다.
    89	        result = { status: 'completed', message: '동기화가 완료되었습니다.' };
    90	      } catch {
    91	        result = { status: 'failed', message: '동기화에 실패했습니다.' };
    92	      }
    93	      inFlightRef.current = null;
    94	      setIsSyncing(false);
    95	      resolveRun(result);
    96	    })();
    97	
    98	    return run;
    99	  }, []);
