   112	      : query.isLoading
   113	        ? 'loading'
   114	        : query.isError
   115	          ? 'error'
   116	          : 'ready';
   117	
   118	  const retry = () => {
   119	    if (policy.activationStatus === 'error') policy.retryActivation();
