     1	/**
     2	 * useAppPolicy Hook
     3	 *
     4	 * 범용 Policy Hook - 모든 Entity의 CRUD 정책을 한 번에 제공
     5	 * 여러 Entity 정책을 동시에 체크해야 할 때 사용
     6	 */
     7	
     8	import { useMemo } from 'react';
     9	import { useDisplayNetworkStatus, useNetworkCheck } from '@/shared/store/network';
    10	import { useGetTripActivation } from '@/entities/trip/data/useGetTripActivation';
    11	import { TRIP_POLICIES, SCHEDULE_POLICIES, EXPENSE_POLICIES, SERVICE_POLICIES } from './constants';
    12	import type { CRUDPermission, ServiceConfig, PolicyKey, ActivationStatus } from './types';
    13	
    14	/**
    15	 * App Policy Context
    16	 *
    17	 * 모든 Entity의 CRUD 정책 + Service 설정
    18	 */
    19	export interface TripContentPermission extends CRUDPermission {
    20	  status:
    21	    | 'ready'
    22	    | 'no-trip'
    23	    | 'activation-loading'
    24	    | 'activation-error'
    25	    | 'offline'
    26	    | 'network-checking'
    27	    | 'network-unavailable';
    28	}
    29	
    30	export interface AppPolicyContext {
    31	  retryActivation: () => void;
    32	  activationStatus: 'active' | 'inactive' | 'loading' | 'error';
    33	  content: TripContentPermission;
    34	  trip: {
    35	    create: CRUDPermission;
    36	    read: CRUDPermission;
    37	    update: CRUDPermission;
    38	    delete: CRUDPermission;
    39	  };
    40	  schedule: {
    41	    create: CRUDPermission;
    42	    read: CRUDPermission;
    43	    update: CRUDPermission;
    44	    delete: CRUDPermission;
    45	  };
    46	  expense: {
    47	    create: CRUDPermission;
    48	    read: CRUDPermission;
    49	    update: CRUDPermission;
    50	    delete: CRUDPermission;
    51	  };
    52	  service: ServiceConfig;
    53	}
    54	
    55	/**
    56	 * 앱 전역 Policy Hook
    57	 *
    58	 * @param tripId - Trip ID (optional)
    59	 * @returns 모든 Entity의 CRUD 정책
    60	 *
    61	 * @example
    62	 * ```tsx
    63	 * // 여러 Entity 정책을 동시에 체크
    64	 * const policy = useAppPolicy(tripId);
    65	 *
    66	 * if (!policy.schedule.create.allowed) {
    67	 *   return <DisabledMessage reason={policy.schedule.create.reason} />;
    68	 * }
    69	 *
    70	 * if (policy.expense.create.mode === 'manual-only') {
    71	 *   return <ManualInputForm />;
    72	 * }
    73	 *
    74	 * // Service 설정도 접근 가능
    75	 * if (policy.service.mapProvider === 'mapbox') {
    76	 *   return <OfflineMap />;
    77	 * }
    78	 * ```
    79	 */
    80	export function useAppPolicy(tripId?: string): AppPolicyContext {
    81	  const networkStatus = useDisplayNetworkStatus();
    82	
    83	  const { data: activation, isError, refetch: refetchActivation } = useGetTripActivation(tripId ?? '');
    84	  const { checkStatus } = useNetworkCheck();
    85	
    86	  const isActivated = activation?.isActivated ?? false;
    87	  const activationStatus = !tripId
    88	    ? 'inactive'
    89	    : isActivated
    90	      ? 'active'
    91	      : isError
    92	        ? 'error'
    93	        : activation === undefined
    94	          ? 'loading'
    95	          : 'inactive';
    96	  const policyActivationStatus: ActivationStatus = activationStatus === 'active' ? 'active' : 'inactive';
    97	
    98	  // unknown도 Remote 기능을 열지 않는다. 현재 4-state 권한 표의 제한 모드를 재사용한다.
    99	  const policyNetworkStatus = networkStatus === 'online' ? 'online' : 'offline';
   100	  const policyKey: PolicyKey = `${policyNetworkStatus}_${policyActivationStatus}`;
   101	
   102	  return useMemo(() => {
   103	    const content: TripContentPermission = !tripId
   104	      ? { allowed: false, status: 'no-trip', reason: '여행을 선택해주세요' }
   105	      : activationStatus === 'loading'
   106	        ? { allowed: false, status: 'activation-loading', reason: '이 기기의 여행 준비 상태를 확인하는 중이에요.' }
   107	        : activationStatus === 'error'
   108	          ? {
   109	              allowed: false,
   110	              status: 'activation-error',
   111	              reason: '여행 준비 상태를 확인하지 못했어요. 다시 시도해주세요.',
   112	            }
   113	          : activationStatus === 'active' || networkStatus === 'online'
   114	            ? { allowed: true, status: 'ready' }
   115	            : networkStatus === 'offline'
   116	              ? {
   117	                  allowed: false,
   118	                  status: 'offline',
   119	                  reason: '오프라인에서는 준비된 활성 여행만 볼 수 있어요. 연결 후 다시 이용해주세요.',
   120	                }
   121	              : checkStatus === 'unavailable'
   122	                ? {
   123	                    allowed: false,
   124	                    status: 'network-unavailable',
   125	                    reason: '인터넷 연결을 확인하지 못했어요. 연결 상태를 재확인해주세요.',
   126	                  }
   127	                : {
   128	                    allowed: false,
   129	                    status: 'network-checking',
   130	                    reason: '인터넷 연결을 확인하는 중이에요. 활성 여행은 계속 이용할 수 있어요.',
   131	                  };
   132	
   133	    const permissions = (table: typeof TRIP_POLICIES) => {
   134	      const permission = (operation: keyof typeof table): CRUDPermission => {
   135	        const value = table[operation][policyKey];
   136	        if ((activationStatus === 'loading' || activationStatus === 'error') && operation !== 'create') {
   137	          return { allowed: false, reason: content.reason };
   138	        }
   139	        if (!value.allowed && networkStatus === 'unknown') {
   140	          return { ...value, reason: '인터넷 연결을 아직 확인하지 못했어요. 잠시 후 다시 시도해주세요.' };
   141	        }
   142	        return value;
   143	      };
   144	      return {
   145	        create: permission('create'),
   146	        read: permission('read'),
   147	        update: permission('update'),
   148	        delete: permission('delete'),
   149	      };
   150	    };
   151	
   152	    return {
   153	      activationStatus,
   154	      retryActivation: () => {
   155	        refetchActivation();
   156	      },
   157	      content,
   158	      trip: permissions(TRIP_POLICIES),
   159	      schedule: { ...permissions(SCHEDULE_POLICIES), read: content },
   160	      expense: { ...permissions(EXPENSE_POLICIES), read: content },
   161	      service:
   162	        SERVICE_POLICIES[
   163	          activationStatus === 'loading' || activationStatus === 'error' ? 'offline_inactive' : policyKey
   164	        ],
   165	    };
   166	  }, [tripId, policyKey, activationStatus, networkStatus, checkStatus, refetchActivation]);
   167	}
import { View, Text } from 'react-native';
import { Pressable } from '@repo/ui';
import { PolicyErrorDisplay } from './PolicyErrorDisplay';
import { useNetworkCheck } from '@/shared/store/network';
import { useGetActiveTrip } from '@/entities/trip/data/useGetTripActivation';
import { useTripStore } from '@/shared/store/useTripStore';
import type { useTripContentAccess } from '@/shared/policy/useTripContentAccess';

type Access = ReturnType<typeof useTripContentAccess>;

export function TripContentStatus({ access }: { access: Access }) {
  const { checkStatus, isRefreshing, refresh } = useNetworkCheck();
  const { data: activeTrip } = useGetActiveTrip();
  const setSelectedTripId = useTripStore((state) => state.setSelectedTripId);

  if (access.status === 'loading') {
    return (
      <View className='flex-1 items-center justify-center p-lg'>
        <Text>여행 내용을 불러오는 중...</Text>
      </View>
    );
  }
  if (access.status === 'error') {
    return (
      <View className='flex-1 items-center justify-center gap-sm p-lg'>
        <Text>여행 내용을 불러오지 못했어요. 다시 시도해주세요.</Text>
        <Pressable onPress={access.retry}>다시 불러오기</Pressable>
      </View>
    );
  }

  const { status } = access.permission;
  const networkRestricted = status === 'offline' || status === 'network-checking' || status === 'network-unavailable';
  return (
    <View className='flex-1 gap-sm p-md'>
      <PolicyErrorDisplay permission={access.permission} variant='inline' />
      {networkRestricted && (
        <>
          {activeTrip ? (
            <Pressable onPress={() => setSelectedTripId(activeTrip.tripId)}>활성 여행으로 돌아가기</Pressable>
          ) : (
            <Text className='text-body text-muted-foreground'>현재 이 기기에서 사용할 수 있는 활성 여행이 없어요.</Text>
          )}
          {(status === 'offline' || status === 'network-unavailable' || checkStatus === 'unavailable') && (
            <Pressable disabled={isRefreshing} onPress={() => refresh()}>
              {isRefreshing ? '연결 확인 중...' : '연결 재확인'}
            </Pressable>
          )}
        </>
      )}
      {status === 'activation-error' && <Pressable onPress={access.retry}>다시 확인하기</Pressable>}
    </View>
  );
}

export function TripRecoveryNotice({ notice }: { notice: string | null }) {
  if (!notice) return null;
  return (
    <View
      accessibilityRole='alert'
      accessibilityLiveRegion='polite'
      className='absolute bottom-md left-md right-md rounded-md bg-muted p-sm'
    >
      <Text className='text-body text-foreground'>{notice}</Text>
    </View>
  );
}
import { isOfflineError } from '@/shared/services/offline-prep/errors';

/** Router의 제한 이유는 보존하고 일반 요청 실패에는 기존 화면 문구를 사용한다. */
export function mutationErrorMessage(error: unknown, fallback: string): string {
  return isOfflineError(error) ? error.message : fallback;
}

