jest.mock('@/entities/trip/api/trips', () => ({
  fetchAllTrips: jest.fn(),
  fetchCreateTrip: jest.fn(),
  fetchUpdateTrip: jest.fn(),
  fetchDeleteTrip: jest.fn(),
}));
jest.mock('@/entities/schedule/lib/schedule-local', () => ({
