import { describe, expect, it, jest } from '@jest/globals';
import { renderHook } from '@testing-library/react-native';

import { useNetworkStore } from '@/shared/store/network';
import { useAppPolicy } from '@/shared/policy/useAppPolicy';
import { useGetTripActivation } from '@/entities/trip/data/useGetTripActivation';

jest.mock('@react-native-community/netinfo', () => ({
  __esModule: true,
  default: { addEventListener: jest.fn(), refresh: jest.fn() },
}));

jest.mock('@/entities/trip/data/useGetTripActivation', () => ({ useGetTripActivation: jest.fn() }));

const activationMock = jest.mocked(useGetTripActivation);

describe('기존 Policy 표의 unknown 호환', () => {
  it.each([true, false])('활성 여부 %s일 때 모든 권한·서비스를 반환하며 Remote 기능은 제한한다', (isActivated) => {
    activationMock.mockReturnValue({ data: { isActivated } } as ReturnType<typeof useGetTripActivation>);
    useNetworkStore.setState({ realStatus: 'unknown', overrideStatus: null });

    const { result } = renderHook(() => useAppPolicy('trip-b'));

    const { trip, schedule, expense, service } = result.current;

    for (const entity of [trip, schedule, expense]) {
      for (const operation of ['create', 'read', 'update', 'delete'] as const) {
        expect(entity[operation]).toBeDefined();
      }
    }

    expect(service.searchMode).toBe('disabled');
    expect(schedule.create.allowed).toBe(isActivated);
    expect(expense.update.allowed).toBe(isActivated);
  });
});

describe('내용 접근 이유와 활성화 확인', () => {
  it('활성화 결과가 없으면 비활성으로 확정하지 않는다', () => {
    activationMock.mockReturnValue({ data: undefined, isLoading: true } as ReturnType<typeof useGetTripActivation>);
    useNetworkStore.setState({ realStatus: 'online', overrideStatus: null });
    const { result } = renderHook(() => useAppPolicy('trip-b'));
    expect(result.current.content.status).toBe('activation-loading');
    expect(result.current.content.allowed).toBe(false);
  });

  it.each(['checking', 'unavailable'] as const)('unknown %s 이유를 내용 제한에 연결한다', (checkStatus) => {
    activationMock.mockReturnValue({ data: null, isLoading: false } as ReturnType<typeof useGetTripActivation>);
    useNetworkStore.setState({ realStatus: 'unknown', overrideStatus: null, checkStatus });
    const { result } = renderHook(() => useAppPolicy('trip-b'));
    expect(result.current.content.allowed).toBe(false);
    expect(result.current.content.status).toBe(checkStatus === 'checking' ? 'network-checking' : 'network-unavailable');
    expect(result.current.schedule.read.allowed).toBe(false);
    expect(result.current.content.reason).not.toContain('오프라인');
  });
});
import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';
import { networkStore, useNetworkStore, type NetworkStatus } from '@/shared/store/network';
import { getTripActivationStatus, hasAnyActivatedTrip } from '@/shared/services/offline-prep/metadata';
import {
  routeTripListQuery,
  routeTripQuery,
  routeTripCreate,
  routeChildQuery,
  routeTripMutation,
  routeChildMutation,
} from '@/shared/services/offline-prep/router';

jest.mock('@react-native-community/netinfo', () => ({
  __esModule: true,
  default: { addEventListener: jest.fn(), refresh: jest.fn() },
}));

jest.mock('@/shared/services/offline-prep/metadata', () => ({
  getTripActivationStatus: jest.fn(),
  hasAnyActivatedTrip: jest.fn(),
}));

const activationMock = jest.mocked(getTripActivationStatus);
const anyActivationMock = jest.mocked(hasAnyActivatedTrip);
const networkStatuses: NetworkStatus[] = ['online', 'offline', 'unknown'];

interface TestOperations {
  local: () => Promise<string>;
  remote: () => Promise<string>;
}

const routeCases = [
  {
    name: 'Trip 목록 조회',
    activationCondition: '전역 활성 여행이 있으면',
    inactiveCondition: '전역 활성 여행이 없으면',
    isMutation: false,
    run: (operations: TestOperations) => routeTripListQuery(operations),
  },
  {
    name: 'Trip 단건 조회',
    activationCondition: '대상 여행이 활성화돼 있으면',
    inactiveCondition: '대상 여행이 비활성이면',
    isMutation: false,
    run: (operations: TestOperations) => routeTripQuery('trip-b', operations),
  },
  {
    name: 'Child 조회',
    activationCondition: '소속 여행이 활성화돼 있으면',
    inactiveCondition: '소속 여행이 비활성이면',
    isMutation: false,
    run: (operations: TestOperations) => routeChildQuery('trip-b', operations),
  },
  {
    name: 'Trip 쓰기',
    activationCondition: '대상 여행이 활성화돼 있으면',
    inactiveCondition: '대상 여행이 비활성이면',
    isMutation: true,
    run: (operations: TestOperations) => routeTripMutation('trip-b', operations),
  },
  {
    name: 'Child 쓰기',
    activationCondition: '소속 여행이 활성화돼 있으면',
    inactiveCondition: '소속 여행이 비활성이면',
    isMutation: true,
    run: (operations: TestOperations) => routeChildMutation('trip-b', operations),
  },
];

function createOperations() {
  return {
    local: jest.fn(async () => 'local'),
    remote: jest.fn(async () => 'remote'),
  };
}

beforeEach(() => {
  useNetworkStore.setState({ realStatus: 'unknown', overrideStatus: null });
  activationMock.mockResolvedValue(false);
  anyActivationMock.mockResolvedValue(false);
});

afterEach(() => networkStore.cleanup());

describe.each(routeCases)('$name의 네트워크 소비', ({ run, activationCondition, inactiveCondition }) => {
  it.each(networkStatuses)(`${activationCondition} %s에서 Local만 실행한다`, async (realStatus) => {
    activationMock.mockResolvedValue(true);
    anyActivationMock.mockResolvedValue(true);
    useNetworkStore.setState({ realStatus });
    const operations = createOperations();

    await expect(run(operations)).resolves.toBe('local');

    expect(operations.local).toHaveBeenCalledTimes(1);
    expect(operations.remote).not.toHaveBeenCalled();
  });

  it.each(['offline', 'unknown'] as const)(
    `${inactiveCondition} %s에서 Remote를 실행하지 않는다`,
    async (realStatus) => {
      useNetworkStore.setState({ realStatus });
      const operations = createOperations();

      await expect(run(operations)).rejects.toMatchObject({
        name: 'OfflineError',
        action: realStatus === 'unknown' ? 'ONLINE_REQUIRED' : 'ACTIVATE_PROMPT',
      });

      expect(operations.local).not.toHaveBeenCalled();
      expect(operations.remote).not.toHaveBeenCalled();
    },
  );

  it('화면 강제 online이 실제 unknown의 Remote 경로를 열지 않는다', async () => {
    networkStore.setOverride('online');
    const operations = createOperations();

    await expect(run(operations)).rejects.toMatchObject({ name: 'OfflineError' });

    expect(operations.remote).not.toHaveBeenCalled();
  });
});

describe.each(routeCases.filter((route) => route.name !== 'Trip 목록 조회'))('$name의 소속 여행 판단', ({ run }) => {
  it('다른 활성 여행이 있어도 소속 여행이 비활성이면 실제 online에서 Remote만 실행한다', async () => {
    anyActivationMock.mockResolvedValue(true);
    activationMock.mockResolvedValue(false);
    useNetworkStore.setState({ realStatus: 'online' });
    const operations = createOperations();

    await expect(run(operations)).resolves.toBe('remote');

    expect(activationMock).toHaveBeenCalledWith('trip-b');
    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).toHaveBeenCalledTimes(1);
  });

  it('전역 활성 판단과 달라도 소속 여행이 활성화돼 있으면 Local만 실행한다', async () => {
    anyActivationMock.mockResolvedValue(false);
    activationMock.mockResolvedValue(true);
    useNetworkStore.setState({ realStatus: 'online' });
    const operations = createOperations();

    await expect(run(operations)).resolves.toBe('local');

    expect(activationMock).toHaveBeenCalledWith('trip-b');
    expect(operations.local).toHaveBeenCalledTimes(1);
    expect(operations.remote).not.toHaveBeenCalled();
  });
});

describe.each(routeCases.filter((route) => !route.isMutation))('$name의 debug 표시와 조회 분리', ({ run }) => {
  it('실제 online이면 화면 override와 관계없이 Remote를 실행한다', async () => {
    useNetworkStore.setState({ realStatus: 'online', overrideStatus: 'offline' });
    const operations = createOperations();

    await expect(run(operations)).resolves.toBe('remote');

    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).toHaveBeenCalledTimes(1);
  });
});

describe.each(routeCases.filter((route) => route.isMutation))('$name의 debug 쓰기 차단', ({ run }) => {
  it('실제 online이어도 화면 override 중에는 비활성 여행의 Remote 변경을 실행하지 않는다', async () => {
    useNetworkStore.setState({ realStatus: 'online', overrideStatus: 'offline' });
    const operations = createOperations();

    await expect(run(operations)).rejects.toThrow('화면 테스트 중');

    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).not.toHaveBeenCalled();
  });

  it('화면 override를 해제하면 실제 online에서 비활성 여행의 Remote 변경을 재개할 수 있다', async () => {
    useNetworkStore.setState({ realStatus: 'online', overrideStatus: 'offline' });
    const operations = createOperations();

    await expect(run(operations)).rejects.toThrow('화면 테스트 중');
    networkStore.setOverride(null);

    await expect(run(operations)).resolves.toBe('remote');

    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).toHaveBeenCalledTimes(1);
  });

  it.each(networkStatuses)('강제 %s 중에는 활성 여행의 Local 변경도 실행하지 않는다', async (overrideStatus) => {
    activationMock.mockResolvedValue(true);
    anyActivationMock.mockResolvedValue(true);
    useNetworkStore.setState({ realStatus: 'online', overrideStatus });
    const operations = createOperations();

    await expect(run(operations)).rejects.toThrow('강제 설정을 해제');

    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).not.toHaveBeenCalled();
  });
});

describe('신규 여행의 서버 생성', () => {
  it('다른 활성 여행이 있어도 실제 online에서 서버로 새 여행을 생성한다', async () => {
    anyActivationMock.mockResolvedValue(true);
    useNetworkStore.setState({ realStatus: 'online' });
    const remote = jest.fn(async () => 'created');
    await expect(routeTripCreate(remote)).resolves.toBe('created');
    expect(remote).toHaveBeenCalledTimes(1);
    expect(anyActivationMock).not.toHaveBeenCalled();
  });

  it.each(['offline', 'unknown'] as const)('%s에서 서버 요청을 시작하지 않는다', async (realStatus) => {
    useNetworkStore.setState({ realStatus });
    const remote = jest.fn(async () => 'created');
    await expect(routeTripCreate(remote)).rejects.toMatchObject({ name: 'OfflineError', action: 'ONLINE_REQUIRED' });
    expect(remote).not.toHaveBeenCalled();
  });

  it.each(networkStatuses)('override %s 중에는 서버 요청을 시작하지 않는다', async (overrideStatus) => {
    useNetworkStore.setState({ realStatus: 'online', overrideStatus });
    const remote = jest.fn(async () => 'created');
    await expect(routeTripCreate(remote)).rejects.toThrow('화면 테스트 중');
    expect(remote).not.toHaveBeenCalled();
  });
});

describe.each(routeCases.filter((route) => route.name !== 'Trip 목록 조회'))('$name 실행 직전 상태 확인', ({ run }) => {
  it('활성 여부 조회 중 offline이 되면 Remote를 실행하지 않는다', async () => {
    let finishActivation!: (isActive: boolean) => void;
    activationMock.mockImplementation(
      () =>
        new Promise((resolve) => {
          finishActivation = resolve;
        }),
    );
    useNetworkStore.setState({ realStatus: 'online' });
    const operations = createOperations();
    const result = run(operations);
    useNetworkStore.setState({ realStatus: 'offline' });
    finishActivation(false);
    await expect(result).rejects.toMatchObject({ name: 'OfflineError' });
    expect(operations.remote).not.toHaveBeenCalled();
  });
});

describe.each(routeCases.filter((route) => route.isMutation))('$name 쓰기 실행 직전 강제 설정 확인', ({ run }) => {
  it('활성 여부를 기다리던 중 override를 켜면 Local 변경도 막는다', async () => {
    let finishActivation!: (isActive: boolean) => void;
    activationMock.mockImplementation(
      () =>
        new Promise((resolve) => {
          finishActivation = resolve;
        }),
    );
    useNetworkStore.setState({ realStatus: 'online' });
    const operations = createOperations();
    const result = run(operations);
    networkStore.setOverride('online');
    finishActivation(true);
    await expect(result).rejects.toThrow('화면 테스트 중');
    expect(operations.local).not.toHaveBeenCalled();
    expect(operations.remote).not.toHaveBeenCalled();
  });
});
