import { useMutation, useQueryClient } from '@tanstack/react-query';
import { db, trips, tripActivations, schedules as schedulesTable, expenses as expensesTable } from '@/shared/db';
import { eq } from 'drizzle-orm';
import { withTransaction, getCurrentISOString } from '@/shared/db/utils';
import apiClient from '@/shared/api/fetcher';
import { tripQueryKeys } from './keys';
import { scheduleQueryKeys } from '@/entities/schedule/data/keys';
import { expenseQueryKeys } from '@/entities/expense/data/keys';
import { routeQueryKeys } from '@/entities/route/data/keys';
import { downloadOfflineMapInBackground } from '@/shared/services/offline-map/download';
import { downloadRoutesForSchedules } from '@/shared/services/directions/route-downloader';
import { generateId } from '@/shared/services/id/ulid';
import { TRIP_ACTIVATION_GRACE_DAYS } from '@/shared/lib/lifecycle';
import type { Trip } from '../model/types';

/**
 * 여행 활성화 Mutation Hook
 *
 * - 서버에서 모든 Trip 메타데이터 + 선택한 여행의 데이터 Pull (일정, 경비 등)
 * - tripActivations 레코드 생성 (Single Source of Truth)
 * - 동시에 1개 여행만 활성화 가능 (기존 활성화된 여행 자동 비활성화)
 * - 오프라인 지도 다운로드 백그라운드 실행
 *
 * @example
 * ```tsx
 * const { mutate: activateTrip, isPending } = useActivateTrip();
 * activateTrip(tripId);
 * ```
 */
export const useActivateTrip = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (tripId: string) => {
      const now = getCurrentISOString();

      // 1. 이미 활성화된 경우 - 경로만 다운로드하고 종료
      const existingActivation = db.select().from(tripActivations).where(eq(tripActivations.tripId, tripId)).get();

      if (existingActivation?.isActivated) {
        console.log(`✅ Trip already activated: ${tripId}, checking routes...`);

        // 이미 활성화되어 있어도 경로 다운로드는 시도 (없는 경로만 다운로드됨)
        const localSchedules = db.select().from(schedulesTable).where(eq(schedulesTable.tripId, tripId)).all();
        if (localSchedules.length > 0) {
          downloadRoutesForSchedules({ tripId, schedules: localSchedules }).catch((error) => {
            console.error('❌ Route download failed for already activated trip:', error);
          });
        }

        return { tripId, alreadyActivated: true };
      }

      // 2. 서버에서 여행 데이터 Pull (모든 Trip + 일정, 경비)
      const response = await apiClient.post(`/api/trips/${tripId}/activate`);

      const { trips: allTrips = [], schedules = [], expenses = [] } = response.data;

      // 3. 활성화하려는 여행 정보 찾기 (서버 응답에서)
      const trip = allTrips.find((t: Trip) => t.id === tripId);

      if (!trip) {
        throw new Error(`Trip not found in server response: ${tripId}`);
      }

      // 4. 트랜잭션: 로컬 DB 업데이트
      await withTransaction(async () => {
        // 4-1. 모든 Trip 메타데이터 저장 (upsert)
        if (allTrips.length > 0) {
          for (const tripData of allTrips) {
            await db
              .insert(trips)
              .values(tripData)
              .onConflictDoUpdate({
                target: trips.id,
                set: {
                  ...tripData,
                  updatedAt: tripData.updatedAt,
                },
              });
          }
          console.log(`💾 Saved ${allTrips.length} trips to local DB`);
        }

        // 4-2. 기존 활성화 레코드 비활성화 (1-Trip 제한, tripActivations만 사용)
        await db
          .update(tripActivations)
          .set({
            isActivated: false,
            deactivatedAt: now,
            updatedAt: now,
          })
          .where(eq(tripActivations.isActivated, true));

        // 4-5. 활성화 레코드 생성 또는 업데이트 (upsert)
        const expiresAt = new Date(trip.endDate);
        expiresAt.setDate(expiresAt.getDate() + TRIP_ACTIVATION_GRACE_DAYS);

        await db
          .insert(tripActivations)
          .values({
            id: generateId(),
            tripId,
            userId: trip.userId,
            isActivated: true,
            activatedAt: now,
            deactivatedAt: null,
            expiresAt: expiresAt.toISOString(),
            syncStatus: 'COMPLETED',
            lastSyncAt: now,
            syncProgress: 100,
            dataDownloaded: true,
            mapDownloaded: false, // 지도는 별도 다운로드
            cleanupPending: false,
            createdAt: now,
            updatedAt: now,
          })
          .onConflictDoUpdate({
            target: tripActivations.tripId,
            set: {
              isActivated: true,
              activatedAt: now,
              deactivatedAt: null,
              expiresAt: expiresAt.toISOString(),
              syncStatus: 'COMPLETED',
              lastSyncAt: now,
              syncProgress: 100,
              dataDownloaded: true,
              updatedAt: now,
            },
          });

        // 4-5. Pull된 데이터 로컬 DB에 저장 (Last-Write-Wins)
        if (schedules.length > 0) {
          for (const schedule of schedules) {
            await db
              .insert(schedulesTable)
              .values(schedule)
              .onConflictDoUpdate({
                target: schedulesTable.id,
                set: {
                  ...schedule,
                  updatedAt: schedule.updatedAt,
                },
              });
          }
          console.log(`💾 Saved ${schedules.length} schedules to local DB`);
        }

        if (expenses.length > 0) {
          for (const expense of expenses) {
            await db
              .insert(expensesTable)
              .values(expense)
              .onConflictDoUpdate({
                target: expensesTable.id,
                set: {
                  ...expense,
                  updatedAt: expense.updatedAt,
                },
            .where(eq(schedules.tripId, tripId));

          // Soft delete: expenses
          await db
            .update(expenses)
            .set({
              deletedAt: now,
              updatedAt: now,
              version: sql`${expenses.version} + 1`,
            })
            .where(eq(expenses.tripId, tripId));

          cleanupExecuted = true;
          console.log(`🗑️ Local data soft-deleted for trip: ${tripId}`);
        }
      });

      // 4-3. 오프라인 지도 정리 (선택적, 트랜잭션 외부에서 실행)
      // cleanup이 즉시 실행된 경우에만 지도도 삭제
      if (cleanupData && cleanupExecuted) {
        try {
          await cleanupOfflineMapForTrip(tripId);
        } catch (error) {
          console.error(`⚠️ Failed to cleanup offline map (ignored):`, error);
          // 지도 정리 실패해도 비활성화는 성공으로 처리
        }
      }

      // 5. 서버에 비활성화 알림 (선택적, 실패해도 무시)
      try {
        await apiClient.post(`/api/trips/${tripId}/deactivate`);
        console.log(`📤 Deactivation notified to server: ${tripId}`);
      } catch (error) {
        console.warn(`⚠️ Failed to notify deactivation to server (ignored):`, error);
      }

      console.log(`✅ Trip deactivated: ${tripId} (cleanup: ${cleanupData}, executed: ${cleanupExecuted})`);

      return {
        tripId,
        alreadyDeactivated: false,
        cleanupData,
        cleanupExecuted,
        cleanupPending: cleanupData && hasPending,
      };
    },
    onSuccess: (data) => {
      // 캐시 무효화 - 여행 목록 및 활성화 상태 다시 조회
      queryClient.invalidateQueries({ queryKey: tripQueryKeys.base });
      queryClient.invalidateQueries({ queryKey: tripQueryKeys.activeTrip() });

      // 정리된 데이터 반영 (Soft delete된 Schedule, Expense, Route)
      if (!data.alreadyDeactivated) {
        queryClient.invalidateQueries({ queryKey: scheduleQueryKeys.base });
        queryClient.invalidateQueries({ queryKey: expenseQueryKeys.base });
        queryClient.invalidateQueries({ queryKey: routeQueryKeys.base });
        console.log(`✅ Trip deactivation completed: ${data.tripId}`);
      }
    },
    onError: (error) => {
      console.error('❌ Failed to deactivate trip:', error);
    },
  });
};

