  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
  // null은 첫 effect 미처리이며, 실제 네트워크의 unknown과 구분한다.
  const previousStatusRef = useRef<NetworkStatus | null>(null);

  /**
   * 동기화 실행 함수 (중복 실행 방지)
   */
  const executeSync = useCallback(
    async (reason: string) => {
      if (networkStore.realStatus !== 'online' || networkStore.override !== null) {
        return;
      }

      if (isSyncing) {
        console.log('⏭️ [SyncProvider] Sync already in progress, skipping...');
        return;
      }

      try {
        setIsSyncing(true);
        console.log(`🔄 [SyncProvider] Sync triggered: ${reason}`);

        await syncData(); // Push + Pull

        const now = new Date();
        setLastSyncedAt(now);

        console.log(`✅ [SyncProvider] Sync completed: ${reason}`, {
          lastSyncedAt: now.toISOString(),
        });
      } catch (error) {
        console.error(`❌ [SyncProvider] Sync failed: ${reason}`, error);
      } finally {
        setIsSyncing(false);
      }
    },
    [isSyncing],
  );

  /**
   * 수동 동기화 트리거 (UI에서 호출)
   */
  const triggerManualSync = useCallback(async () => {
    await executeSync('Manual trigger');
  }, [executeSync]);

  /**
   * 최초 online과 이후 online 전환마다 한 번 동기화
   */
  useEffect(() => {
    const previousStatus = previousStatusRef.current;
    previousStatusRef.current = networkStatus;

    // 최초 unknown 확정과 오프라인 복구 모두 실제 online에서 시작한다.
    if (previousStatus !== 'online' && networkStatus === 'online') {
      if (previousStatus === null) {
        console.log('🚀 [SyncProvider] Initial sync on app start');
        executeSync('App startup');
      } else {
        console.log('🌐 [SyncProvider] Network recovered → Starting sync');
        executeSync('Network recovery');
      }
    }

    // 온라인 → 오프라인 전환 로그
    if (previousStatus === 'online' && networkStatus === 'offline') {
      console.log('📴 [SyncProvider] Network offline → Sync paused');
    }
  }, [networkStatus, executeSync]);

  return null;
}

export default function RootLayout() {
  const colorScheme = useColorScheme();
  const [isAppReady, setIsAppReady] = useState(false);
  const { init: initAuth } = useAuthStore();

  useEffect(() => {
    networkStore.init();

    return () => networkStore.cleanup();
  }, []);

  // 앱 초기화 (DB, 폰트, 인증 등)
  useEffect(() => {
    const prepareApp = async () => {
      try {
        console.log('🚀 Preparing app...');

        // 1. 로컬 DB 초기화
        await initializeDatabase();

        // 2. Auth Store 초기화 (SecureStore에서 토큰 복원)
        await initAuth();

        console.log('✅ App is ready!');
      } catch (error) {
        console.error('❌ Failed to prepare app:', error);
      } finally {
        // 초기화 완료 (성공/실패 무관)
        setIsAppReady(true);
      }
    };

    prepareApp();
  }, [initAuth]);

  // 앱 준비 완료 시 Splash 화면 숨기기
  useEffect(() => {
    if (isAppReady) {
      SplashScreen.hideAsync();
    }
  }, [isAppReady]);

  // Splash 화면 유지 (초기화 완료 전까지)
  if (!isAppReady) {
    return null;
  }

  return (
    <SafeAreaProvider>
      <QueryClientProvider client={queryClient}>
        <SyncProvider>
          {/* 세션 만료 배너 (상단에 표시) */}
  );
}

function assertWritesAllowed() {
  if (networkStore.override !== null) {
    throw new OfflineError('네트워크 화면 테스트 중에는 저장·삭제할 수 없어요. 강제 설정을 해제해주세요.', {
      action: 'ONLINE_REQUIRED',
    });
  }
}

/** Trip 조회의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripQuery<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 조회는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildQuery<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 볼 수 있어요', tripId);
  return await operations.remote();
}

/** Trip 쓰기의 기존 분기는 전역 활성 여행 존재 여부를 사용한다. */
export async function routeTripMutation<T>(operations: RouteOperations<T>): Promise<T> {
  const hasActivated = await hasAnyActivatedTrip();

  assertWritesAllowed();

  if (hasActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요');
  return await operations.remote();
}

/** Schedule·Expense 쓰기는 소속 여행의 활성 여부로 분기한다. */
export async function routeChildMutation<T>(tripId: string, operations: RouteOperations<T>): Promise<T> {
  const isActivated = await getTripActivationStatus(tripId);

  assertWritesAllowed();

  if (isActivated) {
    return await operations.local();
  }

  assertRemoteAvailable('오프라인에서는 활성화된 여행만 수정할 수 있어요', tripId);
  return await operations.remote();
}
