 36	  isDatabaseReady,
 37	  enablePeriodicSync = false,
 38	  syncInterval = 5 * 60 * 1000,
 39	}: SyncProviderProps) {
 40	  const networkStatus = useRealNetworkStatus();
 41	  const overrideStatus = useNetworkStore((state) => state.overrideStatus);
 42	  const isAuthInitialized = useAuthStore((state) => state.isInitialized);
 43	  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
 44	  const canSync =
 45	    isDatabaseReady && isAuthInitialized && isAuthenticated && networkStatus === 'online' && overrideStatus === null;
 46	
 47	  const [isSyncing, setIsSyncing] = useState(false);
 48	  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
 49	  const inFlightRef = useRef<Promise<SyncRunResult> | null>(null);
 50	  const databaseReadyRef = useRef(isDatabaseReady);
 51	  databaseReadyRef.current = isDatabaseReady;
 52	  const previouslyEligibleRef = useRef(false);
 53	
 54	  const executeSync = useCallback((): Promise<SyncRunResult> => {
 55	    // 이전 render의 callback과 자동/수동 호출도 같은 진행 중 실행을 기다린다.
 56	    if (inFlightRef.current) {
 57	      return inFlightRef.current;
 58	    }
 59	
 60	    let blockedMessage: string | null = null;
 61	    if (!databaseReadyRef.current) {
 62	      blockedMessage = '데이터베이스가 준비되지 않아 동기화할 수 없습니다.';
 63	    } else if (!authStore.isInitialized || !authStore.isAuthenticated) {
 64	      blockedMessage = '로그인 준비가 완료된 뒤 동기화할 수 있습니다.';
 65	    } else if (networkStore.override !== null) {
 66	      blockedMessage = '네트워크 강제 설정 중에는 동기화할 수 없습니다. 실제 상태로 되돌려 주세요.';
 67	    } else if (networkStore.realStatus !== 'online') {
 68	      blockedMessage = '인터넷 연결이 확인된 뒤 동기화할 수 있습니다.';
 69	    }
 70	    if (blockedMessage) {
 71	      return Promise.resolve({ status: 'blocked', message: blockedMessage });
 72	    }
 73	
 74	    let resolveRun!: (result: SyncRunResult) => void;
 75	    const run = new Promise<SyncRunResult>((resolve) => {
 76	      resolveRun = resolve;
 77	    });
 78	    // React 표시 상태를 갱신하기 전에 실행 소유권을 선점한다.
 79	    inFlightRef.current = run;
 80	    previouslyEligibleRef.current = true;
 81	    setIsSyncing(true);
 82	
 83	    (async () => {
 84	      let result: SyncRunResult;
 85	      try {
 86	        await syncData();
 87	        setLastSyncedAt(new Date());
 88	        // engine가 반환됐음을 뜻한다. queue 전체 반영 여부는 engine의 결과 계약에 따른다.
 89	        result = { status: 'completed', message: '동기화가 완료되었습니다.' };
 90	      } catch {
 91	        result = { status: 'failed', message: '동기화에 실패했습니다.' };
 92	      }
 93	      inFlightRef.current = null;
 94	      setIsSyncing(false);
 95	      resolveRun(result);
 96	    })();
 97	
 98	    return run;
 99	  }, []);
100	
101	  // 최초 준비 완료, 로그인, 연결 복구, 강제 설정 해제가 같은 시작 경계를 사용한다.
102	  useEffect(() => {
103	    const wasEligible = previouslyEligibleRef.current;
104	    previouslyEligibleRef.current = canSync;
105	    if (canSync && !wasEligible) {
106	      executeSync();
107	    }
108	  }, [canSync, executeSync]);
109	
110	  useEffect(() => {
111	    if (!enablePeriodicSync) {
112	      return;
113	    }
114	    const intervalId = setInterval(() => {
115	      executeSync();
116	    }, syncInterval);
117	    return () => clearInterval(intervalId);
118	  }, [enablePeriodicSync, syncInterval, executeSync]);
119	
120	  return (
121	    <SyncContext.Provider value={{ isSyncing, lastSyncedAt, triggerManualSync: executeSync }}>
122	      {children}
123	    </SyncContext.Provider>
124	  );
125	}
 25	  latest.current = { tripId, realStatus };
 26	  const requestVersion = useRef(0);
 27	  const refetch = useRef(query.refetch);
 28	  refetch.current = query.refetch;
 29	
 30	  useEffect(() => {
 31	    if (recovery.tripId !== tripId) {
 32	      requestVersion.current += 1;
 33	      setNotice(null);
 34	      setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 35	      return;
 36	    }
 37	    if (!tripId || policy.activationStatus !== 'inactive') {
 38	      if (recovery.blocked) {
 39	        requestVersion.current += 1;
 40	        setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 41	      }
 42	      return;
 43	    }
 44	
 45	    if (realStatus !== 'online') {
 46	      setNotice(null);
 47	      requestVersion.current += 1;
 48	      setRecovery((current) => ({
 49	        ...current,
 50	        blocked: true,
 51	        hadOffline: current.hadOffline || realStatus === 'offline',
 52	        phase: 'idle',
 53	      }));
 54	      return;
 55	    }
 56	    if (!recovery.blocked || recovery.phase !== 'idle') return;
 57	
 58	    const version = ++requestVersion.current;
 59	    setRecovery((current) => ({ ...current, phase: 'pending' }));
 60	    refetch.current({ cancelRefetch: false }).then(
 61	      (result) => {
 62	        if (
 63	          version !== requestVersion.current ||
 64	          latest.current.tripId !== tripId ||
 65	          latest.current.realStatus !== 'online'
 66	        )
 67	          return;
 68	        if (result.isError) {
 69	          setRecovery((current) => ({ ...current, phase: 'error' }));
 70	        } else {
 71	          if (recovery.hadOffline) setNotice('연결이 복구되어 여행 내용을 다시 불러왔어요.');
 72	          setRecovery({ tripId, blocked: false, hadOffline: false, phase: 'idle' });
 73	        }
 74	      },
 75	      () => {
 76	        if (version === requestVersion.current && latest.current.tripId === tripId) {
 77	          setRecovery((current) => ({ ...current, phase: 'error' }));
 78	        }
 79	      },
 80	    );
 81	  }, [
 82	    tripId,
 83	    realStatus,
 84	    policy.activationStatus,
 85	    recovery.tripId,
 86	    recovery.blocked,
 87	    recovery.phase,
 88	    recovery.hadOffline,
 89	  ]);
 90	
 91	  useEffect(
 92	    () => () => {
 93	      requestVersion.current += 1;
 94	    },
 95	    [],
 96	  );
 97	
 98	  useEffect(() => {
 99	    if (!notice) return;
100	    const timer = setTimeout(() => setNotice(null), 3500);
101	    return () => clearTimeout(timer);
102	  }, [notice]);
103	
104	  const awaitingRecovery =
105	    recovery.tripId === tripId && recovery.blocked && realStatus === 'online' && policy.activationStatus === 'inactive';
106	  const status = !policy.content.allowed
107	    ? 'restricted'
108	    : awaitingRecovery
109	      ? recovery.phase === 'error'
110	        ? 'error'
111	        : 'loading'
112	      : query.isLoading
113	        ? 'loading'
114	        : query.isError
115	          ? 'error'
116	          : 'ready';
117	
118	  const retry = () => {
119	    if (policy.activationStatus === 'error') policy.retryActivation();
120	    else if (awaitingRecovery) setRecovery((current) => ({ ...current, phase: 'idle' }));
121	    else query.refetch({ cancelRefetch: false });
122	  };
123	
124	  return { status, permission: policy.content, notice, retry };
125	}

